// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }
    function testFuzz_property(address fuzzOwner) public {
        vm.assume(fuzzOwner != address(0));
        vm.prank(address(this));
        c.transferOwnership(fuzzOwner);

        address currentOwner = c.owner();

        assertTrue(currentOwner == fuzzOwner);
    }
}
